<!doctype html><html><head><meta charset="utf-8"><title>Reporte cancelación viaje</title><style>body{font-family:Arial;font-size:12px;margin:18px}h2{margin:0 0 8px}.meta{margin-bottom:12px}.meta b{display:inline-block;min-width:110px}table{border-collapse:collapse;width:100%}th,td{border:1px solid #777;padding:5px}th{background:#eee}.right{text-align:right}.no-print{margin-bottom:12px}@media print{.no-print{display:none}}</style></head><body>
<div class="no-print"><button onclick="window.print()">Imprimir</button></div>
<h2>REPORTE DE CANCELACIÓN DE VIAJE</h2><div class="meta"><b>Cancelación:</b>#<?php echo (int)$cab['cancelacion_id']; ?><br><b>Viaje:</b>#<?php echo (int)$cab['viaje_id']; ?> — <?php echo htmlspecialchars($cab['ruta_nombre']); ?><br><b>Salida original:</b><?php echo htmlspecialchars($cab['viaje_fechasalida'].' '.$cab['viaje_horasalida']); ?><br><b>Vehículo:</b><?php echo htmlspecialchars($cab['vehiculo_placa']); ?><br><b>Causa:</b><?php echo htmlspecialchars($cab['cancelacion_causa']); ?><br><b>Registrado por:</b><?php echo htmlspecialchars($cab['usuario_nombre']); ?> — <?php echo htmlspecialchars($cab['cancelacion_fechahora']); ?></div>
<table><thead><tr><th>Asiento</th><th>Pasajero</th><th>Documento</th><th>Teléfono</th><th>Forma original</th><th>Pagado/ref.</th><th>Gestión</th><th>Viaje destino</th><th>Diferencia</th></tr></thead><tbody>
<?php $total=0;$dev=0;$saldo=0; foreach($detalles as $d){$total+=(float)$d['importe_pagado']; if((float)$d['diferencia_precio']<0)$dev+=abs((float)$d['diferencia_precio']); if((float)$d['diferencia_precio']>0)$saldo+=(float)$d['diferencia_precio']; ?>
<tr><td><?php echo htmlspecialchars($d['asiento_numero']); ?></td><td><?php echo htmlspecialchars($d['pasajero_nombre']); ?></td><td><?php echo htmlspecialchars($d['pasajero_documento']); ?></td><td><?php echo htmlspecialchars($d['pasajero_telefono']); ?></td><td><?php echo htmlspecialchars($d['forma_nombre']); ?></td><td class="right"><?php echo number_format((float)$d['importe_pagado'],2); ?></td><td><?php echo htmlspecialchars($d['gestion_estado']); ?></td><td><?php echo $d['viaje_destino_id']?'#'.(int)$d['viaje_destino_id'].' '.$d['destino_fecha'].' '.$d['destino_hora']:'-'; ?></td><td class="right"><?php echo number_format((float)$d['diferencia_precio'],2); ?></td></tr><?php } ?>
</tbody></table><p><b>Monto de referencia afectado:</b> Bs <?php echo number_format($total,2); ?> &nbsp; <b>Saldos pendientes:</b> Bs <?php echo number_format($saldo,2); ?> &nbsp; <b>Devoluciones pendientes:</b> Bs <?php echo number_format($dev,2); ?></p>
<?php include(APPPATH.'views/viaje/_impresion_automatica.php'); ?>
</body></html>
